from pathlib import Path
import ast
ROOT = Path(__file__).resolve().parent
PKG = ROOT / "qseries_v2/oracle_execution/solana_atomic_executor"
MODULE = '"""MTR-156 transaction-specific ALT proof binding. Read-only; no RPC in default mode."""\nimport argparse\nimport base64\nimport hashlib\nimport json\nfrom pathlib import Path\nfrom types import MappingProxyType\nfrom .mtr_153_v0_alt_account_resolver import _parse_v0\nfrom .mtr_154_trusted_alt_rpc_evidence import verify_transaction_tables, rpc_table, ALTProofError\n\nCANONICAL_ALT = "HSEM6g4Txajd6EHPav7GBanr4eXc5zzSs4cmySthg97r"\n\nclass LinkError(ValueError):\n    pass\n\ndef bind(raw, read_table, expected_table=CANONICAL_ALT):\n    if not isinstance(raw, bytes):\n        raise LinkError("RAW_TRANSACTION_REQUIRED")\n    try:\n        _, instructions, refs = _parse_v0(raw)\n        if not refs:\n            raise LinkError("NO_LOOKUP_REFERENCES")\n        if expected_table not in [key for key, _, _ in refs]:\n            raise LinkError("CANONICAL_ALT_NOT_REFERENCED")\n        proof = verify_transaction_tables(raw, read_table)\n        rows = proof["rpc_proofs"]\n        if len(rows) != len(refs):\n            raise LinkError("INCOMPLETE_PROOF")\n        if any(p["table"] != ref[0] for p, ref in zip(rows, refs)):\n            raise LinkError("LOOKUP_PROOF_ORDER_MISMATCH")\n        if any(not p["owner_checked"] or not p["active_at_rpc_slot"] for p in rows):\n            raise LinkError("INVALID_ALT_PROOF")\n        slots = tuple(p["rpc_slot"] for p in rows)\n        if any(type(x) is not int or x <= 0 for x in slots):\n            raise LinkError("INVALID_RPC_SLOT")\n        if any(p["last_extended_slot"] >= p["rpc_slot"] for p in rows):\n            raise LinkError("ALT_EXTENSION_NOT_MATURE")\n        if len(proof["resolved"]["instructions"]) != len(instructions):\n            raise LinkError("INSTRUCTION_COUNT_MISMATCH")\n        return MappingProxyType({\n            "status": "TRANSACTION_ALT_LINKED_RPC_CONDITIONAL",\n            "transaction_sha256": hashlib.sha256(raw).hexdigest(),\n            "table_ids": tuple(p["table"] for p in rows),\n            "table_hashes": tuple(p["raw_sha256"] for p in rows),\n            "finalized_slots": slots,\n            "resolved_instruction_count": len(instructions),\n            "atomic_two_leg_proven": False,\n            "protected_profit_certified": False,\n            "signing_authorized": False,\n            "broadcast_authorized": False\n        })\n    except LinkError:\n        raise\n    except Exception as exc:\n        raise LinkError("TRANSACTION_ALT_VERIFICATION_FAILED") from exc\n\ndef main(argv=None):\n    ap=argparse.ArgumentParser()\n    ap.add_argument("--transaction-base64-file", type=Path)\n    ap.add_argument("--rpc", default="https://api.mainnet-beta.solana.com")\n    args=ap.parse_args(argv)\n    if args.transaction_base64_file:\n        encoded=args.transaction_base64_file.read_text(encoding="ascii").strip()\n        try:\n            raw=base64.b64decode(encoded, validate=True)\n        except Exception as exc:\n            raise SystemExit("[HOLD] Invalid base64 transaction file") from exc\n        if len(raw)>1232:\n            raise SystemExit("[HOLD] Transaction exceeds Solana size limit")\n        try:\n            proof=bind(raw, lambda table: rpc_table(args.rpc, table))\n        except LinkError as exc:\n            raise SystemExit("[HOLD] "+str(exc)) from exc\n        print("[MTR156_TX_SHA256]", proof["transaction_sha256"])\n        print("[MTR156_TABLES]", ",".join(proof["table_ids"]))\n        print("[MTR156_FINALIZED_SLOTS]", ",".join(map(str,proof["finalized_slots"])))\n        print("[MTR156_LOOKUP_LINK]", proof["status"])\n    else:\n        print("[MTR156] TRANSACTION_SPECIFIC_ALT_LINKER_READY")\n        print("[MTR156_LINK] NOT_RUN_NO_COMPILED_TRANSACTION")\n    print("[ATOMIC_TWO_LEG_PROOF] FALSE")\n    print("[PROTECTED_PROFIT] FALSE")\n    print("[PRIVATE_KEY] NOT_USED")\n    print("[SIGNING] FALSE")\n    print("[BROADCAST] FALSE")\n\nif __name__=="__main__":\n    main()\n'
TEST = 'import unittest, struct, base64\nfrom qseries_v2.oracle_execution.solana_atomic_executor import mtr_156_transaction_alt_link as m\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_154_trusted_alt_rpc_evidence import decode_table, ALT_OWNER, MAX_U64\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_152_native_envelope_inspector import _base58\n\ndef tx(table):\n    b=bytearray(b\'\\x01\'+bytes(64)+b\'\\x80\'+bytes([1,0,1,2]))\n    b+=bytes([1])*32+bytes([2])*32+bytes([3])*32\n    b+=b\'\\x01\'+bytes([1,1,3])+b\'\\x01\\x55\'\n    b+=b\'\\x01\'+table+bytes([1,1,1,2])\n    return bytes(b)\ndef proof(table):\n    data=struct.pack("<IQQBB",1,MAX_U64,100,0,1)+bytes(32)+bytes(2)+b"\\x09"*32+b"\\x0a"*32+b"\\x0b"*32\n    reply={"context":{"slot":101},"value":{"owner":ALT_OWNER,"lamports":1000,\n           "executable":False,"data":[base64.b64encode(data).decode(),"base64"]}}\n    return decode_table(_base58(table),reply)\n\nclass T(unittest.TestCase):\n    def setUp(self):\n        self.table=bytes([8])*32\n        self.key=_base58(self.table)\n        self.raw=tx(self.table)\n        self.p=proof(self.table)\n    def test_transaction_lookup_and_hash_link(self):\n        out=m.bind(self.raw, lambda k:self.p, expected_table=self.key)\n        self.assertEqual(out["table_ids"],(self.key,))\n        self.assertEqual(out["resolved_instruction_count"],1)\n        self.assertFalse(out["protected_profit_certified"])\n    def test_canonical_table_mismatch_hold(self):\n        with self.assertRaises(m.LinkError):\n            m.bind(self.raw,lambda k:self.p)\n    def test_wrong_table_proof_hold(self):\n        other=proof(bytes([7])*32)\n        with self.assertRaises(m.LinkError):\n            m.bind(self.raw,lambda k:other,self.key)\n    def test_no_rpc_if_canonical_absent(self):\n        called=[]\n        with self.assertRaises(m.LinkError):\n            m.bind(self.raw,lambda k:called.append(k), "11111111111111111111111111111111")\n        self.assertFalse(called)\n    def test_malformed_holds(self):\n        with self.assertRaises(m.LinkError):\n            m.bind(b"not a transaction",lambda k:self.p,self.key)\n    def test_invalid_evidence_is_fail_closed(self):\n        with self.assertRaises(m.LinkError):\n            m.bind(self.raw,lambda k:None,self.key)\n    def test_no_trade_authority(self):\n        out=m.bind(self.raw,lambda k:self.p,self.key)\n        self.assertFalse(out["atomic_two_leg_proven"])\n        self.assertFalse(out["signing_authorized"])\n        self.assertFalse(out["broadcast_authorized"])\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n'
for dep in ("mtr_153_v0_alt_account_resolver.py", "mtr_154_trusted_alt_rpc_evidence.py"):
    if not (PKG / dep).is_file():
        raise SystemExit("[HOLD] Missing " + dep)
for code in (MODULE, TEST): ast.parse(code)
(PKG / "mtr_156_transaction_alt_link.py").write_text(MODULE, encoding="utf-8")
(ROOT / "test_mtr_156_transaction_alt_link.py").write_text(TEST, encoding="utf-8")
print("[PASS] MTR-156 installed")
print("[SCOPE] TRANSACTION_SPECIFIC_ALT_LINK; READ_ONLY")
print("[SCANNER] FROZEN")
print("[PRIVATE_KEY] NOT_USED")
print("[SIGNING] FALSE")
print("[BROADCAST] FALSE")
